import{_ as o,o as a,c as i,ag as t}from"./chunks/framework.D9kpkP22.js";const m=JSON.parse('{"title":"Frost","description":"","frontmatter":{"title":"Frost"},"headers":[],"relativePath":"frost/index.md","filePath":"frost/index.md"}'),l={name:"frost/index.md"};function r(s,e,n,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="frost" tabindex="-1">Frost <a class="header-anchor" href="#frost" aria-label="Permalink to &quot;Frost&quot;">​</a></h1><p>Profile-based hotbars, a cosmetics shop and equip menu, particle effects, and Bedrock UI support for Paper 26.2. Player data persists to SQLite and integrates with Vault for economy. Now <code>2.0.10-alpha</code> with fixed Spear/Mace/Wind Charge hotbar and double-chest inventory customizer.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>Profile hotbars with Hotbar Lock enforcement</li><li>Cosmetics shop with Vault pricing</li><li>Equip menu to toggle owned cosmetics</li><li>Particle effects (always-on, trail, surround, burst) with event triggers</li><li>Bedrock UI via Floodgate + Cumulus forms</li><li>SQLite-backed player data (profiles, locks, owned/equipped cosmetics)</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Paper 26.2 <code>26.2.build.123-stable</code>+</li><li>Java 25</li><li>Vault (economy provider)</li><li>Optional: Geyser 2.2.0+ + Floodgate 2.2.0+ for Bedrock crossplay (Cumulus forms)</li><li>Optional: FreeMinecraftModels 2.7.1+ for proper item skins</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Build or download the plugin jar (see <a href="/Plugins/frost/development.html">Development</a>).</li><li>Place the jar in <code>plugins/</code>.</li><li>Start the server to generate <code>plugins/Frost/config.yml</code> and the SQLite database.</li><li>Edit <code>config.yml</code> to suit your server.</li><li>Run <code>/frost reload</code> to apply changes.</li></ol><h2 id="quick-commands" tabindex="-1">Quick Commands <a class="header-anchor" href="#quick-commands" aria-label="Permalink to &quot;Quick Commands&quot;">​</a></h2><ul><li><code>/shop</code> - open the cosmetics shop (Bedrock via Floodgate forms)</li><li><code>/equip</code> - open your equip menu (Bedrock forms)</li><li><code>/inventory</code> (<code>/inv</code> <code>hotbar</code>) - double-chest (54) customizer for hotbar slots 4-9, Gray glass filler for blocked slots</li><li><code>/togglelock</code> - toggle Hotbar Lock on/off</li><li><code>/frost &lt;reload|setprofile|listprofiles|givecosmetic|inventory&gt;</code> - admin tools</li></ul><p>See the full <a href="/Plugins/frost/commands.html">Commands &amp; Permissions</a> and <a href="/Plugins/frost/configuration.html">Configuration</a>.</p><h2 id="support-matrix" tabindex="-1">Support Matrix <a class="header-anchor" href="#support-matrix" aria-label="Permalink to &quot;Support Matrix&quot;">​</a></h2><ul><li>Paper 26.2 <code>26.2.build.123-stable</code>, Java 25</li><li>Economy via Vault</li><li>Bedrock crossplay via Geyser 2.2.0+ + Floodgate 2.2.0+ (Cumulus forms for shop/equip/inventory)</li><li>Item skins via FreeMinecraftModels 2.7.1+ (display entity with armor-stand fallback for Bedrock)</li><li>Fixed hotbar: slots 1-3 locked Spear (TRIDENT) / Mace (MACE) / Wind Charge (WIND_CHARGE) with <code>custom-model-data 1001-1003</code> or <code>fmm_model frost_spear/mace/wind_charge</code></li></ul><h2 id="developer-notes" tabindex="-1">Developer Notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer Notes&quot;">​</a></h2><p>A small public API is available to:</p><ul><li>Set a player’s profile</li><li>Query available profiles</li><li>Manage owned cosmetics</li></ul><p>See <a href="/Plugins/frost/development.html">Development</a> for build and API entry points.</p>',17)])])}const h=o(l,[["render",r]]);export{m as __pageData,h as default};
